namespace BlazorApp.Models;

public class Equipment
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

using BlazorApp.Models;

namespace BlazorApp.Services;

public class EquipmentService
{
    public async Task<List<Equipment>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(500);

        return new List<Equipment>
        {
            new() { Id = 1, Name = "Hydraulic Press", Location = "Building A - Floor 1", LastInspected = new DateTime(2026, 6, 15) },
            new() { Id = 2, Name = "CNC Lathe", Location = "Building A - Floor 2", LastInspected = new DateTime(2026, 5, 22) },
            new() { Id = 3, Name = "Welding Robot", Location = "Building B - Bay 3", LastInspected = new DateTime(2026, 7, 1) },
            new() { Id = 4, Name = "Conveyor Belt #7", Location = "Building C - Shipping", LastInspected = new DateTime(2026, 4, 10) },
            new() { Id = 5, Name = "Air Compressor", Location = "Building A - Basement", LastInspected = new DateTime(2026, 6, 28) },
            new() { Id = 6, Name = "Forklift FL-42", Location = "Warehouse D", LastInspected = new DateTime(2026, 3, 18) },
            new() { Id = 7, Name = "Overhead Crane", Location = "Building B - Bay 1", LastInspected = new DateTime(2026, 7, 5) },
            new() { Id = 8, Name = "Band Saw", Location = "Building A - Floor 1", LastInspected = new DateTime(2026, 5, 30) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@attribute [StreamRendering]
@using BlazorApp.Models
@using BlazorApp.Services
@inject EquipmentService EquipmentService
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_equipment is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _equipment)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Equipment>? _equipment;
    private PersistingComponentStateSubscription _persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        _persistingSubscription = ApplicationState.RegisterOnPersisting(PersistData);

        if (ApplicationState.TryTakeFromJson<List<Equipment>>("equipment", out var restored))
        {
            // Interactive render: reuse data persisted during prerender — no second service call.
            _equipment = restored;
        }
        else
        {
            // Prerender (or first render without persisted state): fetch from service.
            _equipment = await EquipmentService.GetEquipmentAsync();
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson("equipment", _equipment);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _persistingSubscription.Dispose();
    }
}

